/**
 * @file    bsp_usb.c
 * @author  eason
 * @brief   USB CDC (virtual COM port). See bsp_usb.h for the interface.
 *
 *          Pieces from the ST USB device library (generated by CubeMX in USB_DEVICE/):
 *          - hUsbDeviceFS (usb_device.c): the device state. dev_state becomes USBD_STATE_CONFIGURED
 *            once the PC has enumerated the board.
 *          - CDC_Receive_FS (usbd_cdc_if.c): called from the OTG_FS interrupt with each OUT packet.
 *            Its USER CODE 6 calls BSP_USB_OnReceive below, then arms the endpoint for the next packet.
 *          - CDC_Transmit_FS (usbd_cdc_if.c): starts an IN transfer. The library reads the buffer
 *            while the transfer is in flight, so the buffer must stay untouched until TxState
 *            goes back to 0 (set by the library in the interrupt when the PC has taken the data).
 *
 * @version beta
 * @date    2026-11-13
 * @copyright Copyright (c) 2026
 *
 */

#include "bsp_usb.h"
#include "stm32f4xx_hal.h" /* GPIO for re-enumeration, __DMB; only this .c file sees HAL types */
#include "usbd_cdc_if.h"   /* CDC_Transmit_FS, USBD_HandleTypeDef, USBD_CDC_HandleTypeDef */
#include <stddef.h>
#include <string.h>

extern USBD_HandleTypeDef hUsbDeviceFS; /* defined in USB_DEVICE/App/usb_device.c */

/* ------------------------------ private state ------------------------------ */

/* owner is valid only when registered is true. */
static USB_RxConfig_t owner;
static volatile bool registered;

/* The library reads from here during an IN transfer, so it must outlive the caller's buffer. */
static uint8_t tx_buffer[USB_TX_BUFFER_SIZE];

static USB_Stats_t usb_stats;

/* ------------------------------ public functions ------------------------------ */

void BSP_USB_ForceReenumerate(void)
{
    /* The PC detects a device by the pull-up on D+ (PA12). Driving D+ low looks like an unplug.
     * Set the output level BEFORE switching the pin to output, so it never glitches high. */
    __HAL_RCC_GPIOA_CLK_ENABLE();
    HAL_GPIO_WritePin(GPIOA, GPIO_PIN_12, GPIO_PIN_RESET);

    GPIO_InitTypeDef gpio = {0};
    gpio.Pin = GPIO_PIN_12;
    gpio.Mode = GPIO_MODE_OUTPUT_PP;
    gpio.Pull = GPIO_NOPULL;
    gpio.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOA, &gpio);

    HAL_Delay(20); /* the PC needs a few ms of "unplugged" to notice */

    /* Leave the pin low. MX_USB_DEVICE_Init -> HAL_PCD_MspInit switches PA12 back to the USB
     * function, and USBD_Start turns the internal D+ pull-up on: the PC sees a fresh plug-in. */
}

USB_Status_e BSP_USB_RegisterRx(const USB_RxConfig_t *config)
{
    if (config == NULL || config->callback == NULL)
    {
        return USB_ERR_PARAM;
    }
    if (registered)
    {
        return USB_ERR_DUPLICATE;
    }

    owner = *config;
    /* USB is already running, so a packet interrupt can arrive at any moment. The barrier stops
     * the compiler (and CPU) from moving the write of owner after the write of registered:
     * the interrupt must never see registered == true with a half-written owner. */
    __DMB();
    registered = true;
    return USB_OK;
}

bool BSP_USB_IsConnected(void)
{
    return hUsbDeviceFS.dev_state == USBD_STATE_CONFIGURED;
}

USB_Status_e BSP_USB_Transmit(const uint8_t *data, uint16_t len)
{
    if (data == NULL || len == 0u || len > USB_TX_BUFFER_SIZE)
    {
        return USB_ERR_PARAM;
    }
    if (!BSP_USB_IsConnected())
    {
        usb_stats.tx_not_ready++;
        return USB_ERR_NOT_READY;
    }

    /* Check BEFORE copying: if the previous transfer is still in flight, tx_buffer is still being
     * read by the library and must not be overwritten.
     * Only the interrupt changes TxState, and only from 1 to 0, so "checked 0, then copy" is safe
     * as long as Transmit itself is called from one context only. */
    const USBD_CDC_HandleTypeDef *hcdc = (const USBD_CDC_HandleTypeDef *)hUsbDeviceFS.pClassData;
    if (hcdc == NULL || hcdc->TxState != 0u)
    {
        usb_stats.tx_busy++;
        return USB_ERR_BUSY;
    }

    memcpy(tx_buffer, data, len);
    if (CDC_Transmit_FS(tx_buffer, len) != USBD_OK)
    {
        usb_stats.tx_busy++;
        return USB_ERR_BUSY;
    }

    usb_stats.tx_ok++;
    return USB_OK;
}

const USB_Stats_t *BSP_USB_GetStats(void)
{
    return &usb_stats;
}

/* ------------------------------ glue ------------------------------ */

void BSP_USB_OnReceive(const uint8_t *data, uint32_t len)
{
    /* Counted even without an owner, so the link can be tested before any protocol exists. */
    usb_stats.rx_packets++;
    usb_stats.rx_bytes += len;

    if (!registered || data == NULL || len == 0u)
    {
        return;
    }
    /* len <= 64 (one full-speed packet), so the cast is safe. */
    owner.callback(data, (uint16_t)len, owner.owner);
}